window.KH_SURA(89, {"sura": "الفجر", "n": 89, "ayat": {"1": "وَالْفَجْرِ", "2": "وَلَيَالٍ عَشْرٍ", "3": "وَالشَّفْعِ وَالْوَتْرِ", "4": "وَاللَّيْلِ إِذَا يَسْرِ", "5": "هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ", "6": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ", "7": "إِرَمَ ذَاتِ الْعِمَادِ", "8": "الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلَادِ", "9": "وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ", "10": "وَفِرْعَوْنَ ذِي الْأَوْتَادِ", "11": "الَّذِينَ طَغَوْا فِي الْبِلَادِ", "12": "فَأَكْثَرُوا فِيهَا الْفَسَادَ", "13": "فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ", "14": "إِنَّ رَبَّكَ لَبِالْمِرْصَادِ", "15": "فَأَمَّا الْإِنْسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ", "16": "وَأَمَّا إِذَا مَا ابْتَلَاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ", "17": "كَلَّا بَلْ لَا تُكْرِمُونَ الْيَتِيمَ", "18": "وَلَا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ", "19": "وَتَأْكُلُونَ التُّرَاثَ أَكْلًا لَمًّا", "20": "وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا", "21": "كَلَّا إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا", "22": "وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا", "23": "وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنْسَانُ وَأَنَّى لَهُ الذِّكْرَى", "24": "يَقُولُ يَالَيْتَنِي قَدَّمْتُ لِحَيَاتِي", "25": "فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُ أَحَدٌ", "26": "وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ", "27": "يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ", "28": "ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً", "29": "فَادْخُلِي فِي عِبَادِي", "30": "وَادْخُلِي جَنَّتِي"}, "units": [{"aya": 1, "title": "في الذي عنى بذلك ﴿الفجر وليال عشر والشفع والوتر والليل إذا يسر هل في ذلك قسم لذي حجر﴾", "tabari": {"page": "24/344", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى به النهار", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [82908, 82911, 82912]}, {"n": 2, "t": "بل عنى به صلاة الفجر", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [82908, 82911, 82912]}, {"n": 3, "t": "هو فجر الصبح", "taqdim": 0, "n_athar": 2, "qailun": [["عكرمة", "تابعي"], ["عبد الله بن الزبير", "صحابي"]], "athar": [82913]}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["089_001_1.png"], "pages": [562], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 1, "title": "معنى الآية", "mawsua": {"taliq": 7151, "masala": "معنى الآية", "sigha": "زاد قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "المراد: فجر العيون من الصخور وغيرها", "ashab": "", "athar": []}, {"n": 2, "t": "المراد: فجر يوم الجمعة", "ashab": "عكرمة", "athar": []}]}, "mawaqif": [{"taliq": 7151, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "8/ 604", "qawl": "", "nass": "وقيل: المراد: فجر العيون من الصخور وغيرها. وقال عكرمة: المراد: فجر يوم الجمعة", "qawaid": [], "tabi": ""}, {"taliq": 7151, "mi": 1, "aya": 1, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "3/ 296", "qawl": "", "nass": "إن أريد به جنس الفجر كما هو ظاهر اللفظ فإنه يتضمن وقت صلاة الصبح، التي هي أول الصلوات، فافتتح القسم بما يتضمن أول الصلوات، وختمه بقوله: {والليل إذا يسر} المتضمن لآخر الصلوات: وإن أريد بالفجر فجر مخصوص فهو فجر يوم النحر وليلته التي هي ليلة عرفة، فتلك الليلة من أفضل ليالي العام، وما رئي الشيطان في ليلة أدحر ولا أحقر ولا أغيظ منه فيها، وذلك الفجر فجر يوم النحر الذي هو أفضل الأيام عند الله … وعلى هذا فقد تضمن القسم المناسك والصلوات، وهما المختصان بعبادة الله والخضوع له والتواضع لعظمته، ولهذا قال الخليل عليه السلام: {قل إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين} [الأنعام: 162]، وقيل لخاتم الرسل صلى الله عليه وسلم: {فصل لربك وانحر} [الكوثر: 2]، بخلاف حال المشركين المتكبرين الذين لا يعبدون الله وحده، بل يشركون به، ويستكبرون عن عبادته كحال من ذكر في هذه السورة من قوم عاد وثمود وفرعون", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 2, "title": "في هذه الليالي العشر، أي ليال هي", "tabari": {"page": "24/345", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندنا أنها عشر الأضحى؛ لإجماع الحجة من أهل التأويل عليه، وأن عبد الله بن أبي زياد القطواني حدثني، قال: ثني زيد بن حباب، قال: أخبرنى عياش بن عقبة، قال: ثني خير بن نعيم، عن أبي الزبير، عن جابر، أن رسول الله ﷺ قال: \" ﴿والفجر (١) وليال عشر﴾ \". قال: \"عشر: الأضحى\" .", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي ليالى عشر ذي الحجة", "taqdim": 0, "n_athar": 12, "qailun": [["ابن عباس", "صحابي"], ["عبد الله بن الزبير", "صحابي"], ["مسروق", "تابعي"], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [82925, 82926, 82927, 82928, 82932, 82933, 82934, 82935, 82937, 82941, 82942, 82943]}, {"n": 2, "t": "هي عشر المحرم من أوله", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 7152, "mi": 1, "aya": 2, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 348", "qawl": "الأول", "nass": "لإجماع الحجة من أهل التأويل عليه، وأن عبد الله بن أبي زياد القطواني حدثني قال: ثني زيد بن حباب، قال: أخبرني عياش بن عقبة، قال: ثني خير بن نعيم، عن أبي الزبير، عن جابر، أن رسول الله صلى الله عليه وسلم قال: {والفجر وليال عشر}، قال: «عشر الأضحى»", "qawaid": ["السنة", "الإجماع"], "tabi": ""}, {"taliq": 7152, "mi": 1, "aya": 2, "alam": "ابن كثير", "fil": "رجحه", "kind": "ترجيح", "ref": "14/ 338", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 7152, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "8/ 604، 605", "qawl": "", "nass": "هي العشر الأول من رمضان", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["089_002_1.png"], "pages": [562], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 7152, "masala": "«الليالي العشر» ما هي؟", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هي ليال عشر ذي الحجة", "ashab": "", "athar": []}, {"n": 2, "t": "العشر الأول من المحرم", "ashab": "", "athar": []}, {"n": 3, "t": "العشر الأواخر من رمضان", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]], "2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السنة", "الإجماع"]}, "rulesD": {}}}, {"aya": 3, "title": "في الذي عنى به من [الشفع بقوله: ﴿والشفع﴾، والذي عنى به من] الوتر بقوله: ﴿والوتر﴾", "tabari": {"page": "24/348", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أقسم بالشفع والوتر، ولم يخصص نوعا من الشفع ولا من الوتر دون نوع بخبر ولا عقل، فكل شفع ووتر فهو مما أقسم به، مما قال أهل التأويل إنه داخل في قسمه هذا؛ لعموم قسمه بذلك.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الشفع يوم النحر، والوتر يوم عرفة", "taqdim": 0, "n_athar": 10, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"], ["عكرمة", "تابعي"], ["الضحاك", "تابعي"]], "athar": [82957, 82958, 82959, 82960, 82961, 82971, 82979, 82981]}, {"n": 2, "t": "الشفع اليومان بعد يوم النحر، والوتر اليوم الثالث", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "الشفع الخلق كله، والوتر الله", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["أبي صالح", "تابعي"]], "athar": [82957, 82958, 82959, 82960, 82961, 82966, 82967, 82968, 82969, 82970, 82977]}, {"n": 4, "t": "عنى بذلك الخلق، وذلك أن الخلق كله شفع ووتر", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["معمر", "تابع التابعين"], ["ابن زيد", "تابع التابعين"]], "athar": [82966, 82967, 82968, 82969, 82970]}, {"n": 5, "t": "بل ذلك الصلاة المكتوبة؛ منها الشفع كصلاة الفجر والظهر، ومنها الوتر كصلاة المغرب", "taqdim": 0, "n_athar": 10, "qailun": [["قتادة", "تابعي"], ["الربيع بن أنس", "تابعي"], ["عمران بن حصين", "صحابي"], ["جابر", "صحابي"]], "athar": [82949, 82950, 82951, 82956, 82964, 82979, 82981]}]}, "mawaqif": [{"taliq": 7153, "mi": 1, "aya": 3, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 355", "qawl": "العموم", "nass": "إن الله -تعالى ذكره- أقسم بالشفع والوتر، ولم يخصص نوعا من الشفع ولا من الوتر دون نوع بخبر ولا عقل، فكل شفع ووتر فهو مما أقسم به مما قال أهل التأويل إنه داخل في قسمه هذا؛ لعموم قسمه بذلك", "qawaid": [], "tabi": ""}, {"taliq": 7153, "mi": 1, "aya": 3, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "8/ 605 - 606", "qawl": "", "nass": "وقيل: الشفع: الصفا والمروة، والوتر: البيت. وقال الحسين بن الفضل: الشفع: أبواب الجنة لأنها ثمانية أبواب، والوتر: أبواب النار لأنها سبعة أبواب. وقال مقاتل: الشفع: الأيام والليالي، والوتر: يوم القيامة؛ لأنه لا ليل بعده. وقال أبو بكر الوراق: الشفع: تضاد أوصاف المخلوقين كالعز والذل ونحوه، والوتر: اتحاد صفات الله تعالى، عز محض وكرم محض، ونحوه. وقيل: الشفع: قران الحج والعمرة، والوتر: الإفراد بالحج … وقال بعض المفسرين: الشفع: حواء، والوتر: آدم? … وقال بعض العلماء: الشفع: تنفل الليل مثنى مثنى، والوتر: الركعة الأخيرة المعروفة", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["089_003_1.png"], "pages": [562], "n": 5, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 7153, "masala": "معنى: «الشفع والوتر»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الشفع: يوم النحر، والوتر: يوم عرفة", "ashab": "", "athar": []}, {"n": 2, "t": "الشفع: اليومان بعد يوم النحر، والوتر: اليوم الثالث", "ashab": "", "athar": []}, {"n": 3, "t": "الشفع: الخلق كله، والوتر: الله", "ashab": "", "athar": []}, {"n": 4, "t": "الشفع والوتر: الخلق كله", "ashab": "", "athar": []}, {"n": 5, "t": "الصلاة المكتوبة؛ منها الشفع، ومنها الوتر", "ashab": "", "athar": []}, {"n": 6, "t": "العدد؛ منه الشفع، ومنه الوتر", "ashab": "", "athar": []}, {"n": 7, "t": "الشفع الركعتان من المغرب، والوتر الركعة الثالثة", "ashab": "", "athar": []}, {"n": 8, "t": "الشفع الأيام والليالي، والوتر يوم القيامة لأنه لا ليل بعده", "ashab": "", "athar": []}, {"n": 9, "t": "الشفع آدم وحواء?، والوتر الله عز وجل", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 4, "title": "تأويل: ﴿والليل إذا يسر﴾", "tabari": {"page": "24/356", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿والليل إذا يسر﴾. يقول: والليل إذا سار فذهب. يقال منه: سرى فلان ليلا يسرى. إذا سار.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "عنى بقوله: ﴿والليل إذا يسر﴾. ليلة جمع، وهى ليلة المزدلفة", "taqdim": 0, "n_athar": 7, "qailun": [["عبد الله بن الزبير", "صحابي"], ["مجاهد", "تابعي"], ["أبي العالية", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"], ["عكرمة", "تابعي"]], "athar": [82989, 82990, 82991, 82992, 82994, 82998, 83001]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "معنى: {إرم}", "mawsua": {"taliq": 7157, "masala": "معنى: {إرم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها اسم بلدة، واختلف في تعيينها على قولين: أحدهما: الإسكندرية", "ashab": "", "athar": []}, {"n": 2, "t": "دمشق. الثاني: عني بها: أمة", "ashab": "", "athar": []}, {"n": 3, "t": "القديمة", "ashab": "", "athar": []}, {"n": 4, "t": "أنها قبيلة من عاد", "ashab": "", "athar": []}, {"n": 5, "t": "هو جد عاد", "ashab": "", "athar": []}, {"n": 6, "t": "الهالك", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "14/ 343", "qawl": "الرابع", "nass": "وهذا قول حسن جيد قوي", "qawaid": [], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "24/ 364", "qawl": "", "nass": "أن يقال: إن إرم إما اسم بلدة كانت عاد تسكنها، فلذلك ردت على عاد على الإتباع لها، ولم تجر من أجل ذلك، وإما اسم قبيلة فلم تجر أيضا كما لا تجرى أسماء القبائل كتميم وبكر وما أشبه ذلك إذا أرادوا به قبيلة", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن كثير", "fil": "انتقده", "kind": "نقد", "ref": "14/ 345", "qawl": "", "nass": "وقول ابن جرير: يحتمل أن يكون المراد بقوله: {إرم} قبيلة أو بلدة كانت عاد تسكنها فلذلك لم تصرف. فيه نظر؛ لأن المراد من السياق إنما هو الإخبار عن القبيلة، ولهذا قال بعده: {وثمود الذين جابوا الصخر بالواد}، يعني: يقطعون الصخر بالوادي", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الرابع", "nass": "وأشبه الأقوال فيه بالصواب عندي: أنها اسم قبيلة من عاد، ولذلك جاءت القراءة بترك إضافة عاد إليها، وترك إجرائها، كما يقال: ألم تر ما فعل ربك بتميم نهشل. فترك نهشل -وهي قبيلة- فترك إجراؤها لذلك، وهي في موضع خفض بالرد على تميم، ولو كانت", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "24/ 364", "qawl": "الثالث", "nass": "قول لا معنى له؛ لأن ذلك لو كان معناه لكان مخفوضا بالتنوين، وفي ترك الإجراء الدليل على أنه ليس بنعت ولا صفة", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "8/ 607", "qawl": "", "nass": "وهذان القولان ضعيفان", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 7157, "mi": 1, "aya": 5, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "14/ 344", "qawl": "", "nass": "ومن زعم أن المراد بقوله: {إرم ذات العماد} مدينة إما دمشق، كما روي عن سعيد بن المسيب، وعكرمة، أو إسكندرية كما روي عن القرظي أو غيرهما، ففيه نظر، فإنه كيف يلتئم الكلام على هذا: {ألم تر كيف فعل ربك بعاد إرم ذات العماد} إن جعل ذلك بدلا أو عطف بيان، فإنه لا يتسق الكلام حينئذ. ثم المراد إنما هو الإخبار عن إهلاك القبيلة المسماة بعاد، وما أحل الله بهم من بأسه الذي لا يرد، لا أن المراد الإخبار عن مدينة أو إقليم", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": "ابن عطية"}], "tags": {"m": {"4": [["ابن جرير", "r"]], "3": [["ابن جرير", "d"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["القراءة ورسم المصحف"], "ابن كثير": ["السياق", "الدلالة العقلية"]}, "rulesD": {"ابن كثير": ["السياق"], "ابن جرير": ["اللغة"], "ابن عطية": ["السياق", "الدلالة العقلية"]}}}, {"aya": 7, "title": "في معنى قوله: ﴿إرم﴾", "tabari": {"page": "24/361", "sarih": 1, "tarjih": "وأشبه الأقوال فيه بالصواب عندى أنها اسم قبيلة من عاد؛ ولذلك جاءت القراءة بترك إضافة عاد إليها وترك إجرائها، كما يقال: ألم تر ما فعل ربك بتميم نهشل. فترك نهشل، وهى قبيلة فترك إجراؤها لذلك، وهي في موضع خفض بالرد على تميم، ولو كانت ﴿إرم﴾ اسم بلدة أو اسم جد لعاد لجاءت القراءة بإضافة عاد إليها، كما يقال: هذا عمرو زبيد وحاتم طيئ وأعشى همدان، ولكنها اسم قبيلة منها فيما أرى كما قال قتادة والله أعلم؛ فلذلك أجمعت القرأة فيها على ترك الإضافة وترك الإجراء.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي اسم بلدة", "taqdim": 0, "n_athar": 2, "qailun": [["أبي صخر عن القرظي", ""], ["المقبري", ""]], "athar": []}, {"n": 2, "t": "عنى بقوله: ﴿إرم﴾ أمة", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [83035, 83036]}, {"n": 3, "t": "معنى ذلك: القديمة", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [83035, 83036]}, {"n": 4, "t": "تلك قبيلة من عاد", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن إسحاق", "تابع التابعين"]], "athar": [83039]}, {"n": 5, "t": "﴿إرم﴾: الهالك", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [83034]}]}, "mawaqif": [{"taliq": 7159, "mi": 1, "aya": 8, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 368", "qawl": "الأول", "nass": "وهذا قول لا وجه له؛ لأن {العماد} واحد مذكر، و {التي} للأنثى، ولا يوصف المذكر بالتي، ولو كان ذلك من صفة {العماد} لقيل: الذي لم يخلق مثله في البلاد، وإن جعلت {التي} لإرم، وجعلت الهاء عائدة في قوله: {مثلها} عليها، وقيل: هي دمشق أو الإسكندرية؛ فإن بلاد عاد هي التي وصفها الله في كتابه، فقال: {واذكر أخا عاد إذ أنذر قومه بالأحقاف} [الأحقاف: 21]، والأحقاف: هي جمع حقف، وهو ما انعطف من الرمل وانحنى، وليست الإسكندرية ولا دمشق من بلاد الرمال، بل ذلك الشحر من بلاد حضرموت، وما والاها", "qawaid": ["اللغة", "التاريخ والواقع"], "tabi": ""}, {"taliq": 7159, "mi": 1, "aya": 8, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "14/ 343", "qawl": "", "nass": "وهذا القول هو الصواب، وقول ابن زيد ومن ذهب مذهبه ضعيف؛ لأنه لو كان أراد ذلك لقال: التي لم يعمل مثلها في البلاد، وإنما قال: {لم يخلق مثلها في البلاد}", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 4, "imgs": ["089_004_1.png", "089_004_2.png"], "pages": [562, 563], "n": 4, "rajih": [3], "daif": [2], "match": false}, "mawsua": {"taliq": 7159, "masala": "المشار إليه بقوله تعالى: {التي لم يخلق مثلها في البلاد}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الإشارة إلى عاد أو تلك القبيلة، والمعنى: لم يخلق مثلها في الطول والقوة", "ashab": "", "athar": []}, {"n": 2, "t": "الإشارة إلى المدينة، والمعنى: لم يخلق مثل الأعمدة في البلاد، وقالوا: التي لم يخلق مثلها من صفة ذات العماد، والهاء التي في {مثلها} إنما هي من ذكر {ذات العماد}", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {"4": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة", "التاريخ والواقع"]}, "rulesD": {}}}, {"aya": 7, "title": "في معنى قوله: ﴿ذات العماد﴾ في هذا الموضع", "tabari": {"page": "24/364", "sarih": 1, "tarjih": "وأشبه الأقوال في ذلك بما دل عليه ظاهر التنزيل قول من قال: عنى بذلك أنهم كانوا أهل عمود سيارة؛ لأن المعروف في كلام العرب من العماد، ما عمد به الخيام من الخشب، أو السوارى التي يحمل عليها البناء، ولا يعلم بناء كان لهم بالعماد بخبر صحيح، بل وجه بعض أهل التأويل قوله: ﴿ذات العماد﴾ إلى أنه عنى به طول أجسامهم، وبعضهم إلى أنه عنى به عماد خيامهم، فأما عماد البنيان، فلا نعلم كبير أحد من أهل التأويل وجهه إليه، وتأويل القرآن إنما يوجه إلى الأعرف الأغلب الأشهر من معانيه - ما وجد إلى ذلك سبيل - دون الأنكر.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: ذات الطول. وذهبوا في ذلك إلى قول العرب للرجل الطويل: رجل معمد. وقالوا: كانوا طوال الأجسام", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [83034, 83035, 83036]}, {"n": 2, "t": "بل قيل لهم: ﴿ذات العماد﴾؛ لأنهم كانوا أهل عمد، ينتجعون الغيوث وينتقلون إلى الكلأ حيث كان، ثم يرجعون إلى منازلهم", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [83035, 83036, 83039]}, {"n": 3, "t": "بل قيل ذلك لهم؛ لبناء بناه بعضهم، فشيد عمده ورفع بناءه", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [83044]}, {"n": 4, "t": "قيل ذلك لهم؛ لشدة أبدانهم وقوتهم", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 7158, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 366 - 367", "qawl": "الثاني", "nass": "لأن المعروف في كلام العرب من العماد: ما عمد به الخيام من الخشب، أو السواري التي يحمل عليها البناء، ولا يعلم بناء كان لهم بالعماد بخبر صحيح، بل وجه بعض أهل التأويل قوله: {ذات العماد} إلى أنه عني به طول أجسامهم، وبعضهم إلى أنه عني به عماد خيامهم، فأما عماد البنيان فلا نعلم كبير أحد من أهل التأويل وجهه إليه، وتأويل القرآن إنما يوجه إلى الأعرف الأغلب الأشهر من معانيه -ما وجد إلى ذلك سبيل- دون الأنكر", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 7158, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 608", "qawl": "", "nass": "قال:", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["089_005_1.png"], "pages": [563], "n": 4, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 7158, "masala": "معنى: {ذات العماد}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ذات الطول، وقالوا: كانوا طوال الأجسام", "ashab": "", "athar": []}, {"n": 2, "t": "ذات العماد؛ لأنهم كانوا أهل خيام وأعمدة، ينتجعون الغيوث", "ashab": "", "athar": []}, {"n": 3, "t": "لبناء بناه بعضهم، فشيد عمده ورفع بناءه", "ashab": "", "athar": []}, {"n": 4, "t": "ذات القوة والشدة", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 8, "title": "تأويل: ﴿التي لم يخلق مثلها في البلاد﴾", "tabari": {"page": "24/367", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿التي لم يخلق مثلها في البلاد﴾. يقول جل ثناؤه: ألم تر كيف فعل ربك بعاد، إرم التي لم يخلق مثلها؛ يعنى: مثل عاد، والهاء عائدة على عاد. وجائز أن تكون عائدة على إرم؛ لما قد بينا قبل أنها قبيلة. وإنما عنى بقوله: ﴿لم يخلق مثلها﴾: [لم يخلق مثلها] في العظم والبطش والأيد.", "taqdim": 1, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [83046]}, {"n": 2, "t": "بل معنى ذلك ذات العماد التي لم يخلق مثل الأعمدة في البلاد. وقالوا: ﴿التي لم يخلق مثلها﴾ من صفة هو ﴿ذات العماد﴾، والهاء التي في ﴿مثلها﴾ إنما هي من ذكر ﴿ذات العماد﴾", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في معنى قوله: ﴿ذي الأوتاد﴾. ولم قيل له كذلك", "tabari": {"page": "24/370", "sarih": 1, "tarjih": "وأولى هذه الأقوال عندى بالصواب قول من قال: عنى بذلك الأوتاد التي توتد، من خشب كانت أو حديد؛ لأن ذلك هو المعروف من معاني الأوتاد، ووصف بذلك؛ لأنه إما أن يكون كان يعذب الناس بها، كما قال أبو رافع وسعيد بن جبير، وإما أن يكون كان يلعب له بها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معنى ذلك: ذى الجنود الذين يقوون له أمره. وقالوا: الأوتاد في هذا الموضع: الجنود", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [83061, 83062, 83063]}, {"n": 2, "t": "بل قيل له ذلك؛ لأنه كان يوتد الناس بالأوتاد", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [83067]}, {"n": 3, "t": "كانت مظال وملاعب يلعب له تحتها", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["أبي رافع", "صحابي"]], "athar": [83064, 83069, 83070]}, {"n": 4, "t": "بل قيل ذلك له؛ لأنه كان يعذب الناس بالأوتاد", "taqdim": 0, "n_athar": 2, "qailun": [["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"]], "athar": [83065, 83066, 83067]}, {"n": 5, "t": "إنما قيل ذلك له لأنه كان له بنيان يعذب الناس عليه", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد بن جبير", "تابعي"]], "athar": [83065, 83066]}]}, "mawaqif": [{"taliq": 7161, "mi": 1, "aya": 10, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 373", "qawl": "الثاني", "nass": "عني بذلك: الأوتاد التي توتد، من خشب كانت أو حديد؛ لأن ذلك هو المعروف من معاني الأوتاد، ووصف بذلك لأنه إما أن يكون كان يعذب الناس بها، كما قال أبو رافع وسعيد بن جبير، وإما أن يكون كان يلعب له بها", "qawaid": ["اللغة"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["089_006_1.png"], "pages": [563], "n": 5, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 7161, "masala": "معنى: {ذي الأوتاد}، ولم قيل لفرعون كذلك؟", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ذي الجنود الذين يقوون له أمره؛ فالأوتاد في هذا الموضع: الجنود", "ashab": "", "athar": []}, {"n": 2, "t": "قيل له ذلك لأنه كان يوتد الناس بالأوتاد", "ashab": "", "athar": []}, {"n": 3, "t": "ذي البناء المحكم", "ashab": "", "athar": []}, {"n": 4, "t": "كانت مظال وملاعب يلعب له تحتها", "ashab": "", "athar": []}, {"n": 5, "t": "قيل له ذلك لأنه كان يعذب الناس بالأوتاد", "ashab": "", "athar": []}, {"n": 6, "t": "قيل له ذلك لأنه كان له بنيان يعذب الناس عليه", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 14, "title": "في تأويله", "tabari": {"page": "24/374", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى قوله: ﴿لبالمرصاد﴾: بحيث يرى ويسمع", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [83083]}, {"n": 2, "t": "يعنى بذلك أنه بمرصد لأهل الظلم", "taqdim": 0, "n_athar": 4, "qailun": [["الضحاك في هذه الآية", "تابعي"], ["سفيان", "تابع التابعين"], ["الحسن", "تابعي"]], "athar": [83085, 83093]}]}, "mawaqif": [], "mushid": {"i": 7, "imgs": ["089_007_1.png"], "pages": [563], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "في المعني بقوله: ﴿كلا﴾. في هذا الموضع، وما الذي أنكر بذلك", "tabari": {"page": "24/377", "sarih": 1, "tarjih": "وأولى القولين في ذلك عندنا بالصواب القول الذي ذكرناه عن قتادة؛ لدلالة قوله: ﴿بل لا تكرمون اليتيم﴾. والآيات التي بعدها، على أنه إنما أهان من أهان بأنه لا يكرم اليتيم، ولا يحض على طعام المسكين، وسائر المعاني التي عدد، وفي إبانته عن السبب الذي من أجله أهان من أهان، الدلالة الواضحة على سبب تكريمه من أكرم، وفي تبيينه ذلك عقيب قوله: ﴿فأما الإنسان إذا ما ابتلاه ربه فأكرمه ونعمه فيقول ربي أكرمن (١٥) وأما إذا ما ابتلاه فقدر عليه رزقه فيقول ربي أهانن﴾ - بيان واضح عن أن الذي أنكر من قوله، ما وصفنا.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "أنكر جل ثناؤه أن يكون سبب كرامته من أكرم كثرة ماله، وسبب إهانته من أهان قلة ماله", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": []}, {"n": 2, "t": "بل أنكر جل ثناؤه حمد الإنسان ربه على نعمه دون فقره، وشكواه الفاقة. وقالوا: معنى الكلام: كلا، أي لم يكن ينبغي أن يكون هكذا، ولكن كان ينبغى أن يحمده على الأمرين جميعا؛ على الغني والفقر", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 8, "imgs": ["089_008_1.png"], "pages": [564], "n": 2, "rajih": [2], "daif": [], "match": true}, "tags": {"m": {}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "قراءة قوله تعالى: {ولا تحاضون}", "mawsua": {"taliq": 7165, "masala": "قراءة قوله تعالى: {ولا تحاضون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{تحاضون} بالتاء وفتحها وإثبات الألف، بمعنى: ولا يحض بعضكم بعضا على طعام المسكين", "ashab": "", "athar": []}, {"n": 2, "t": "تحضون» بالتاء وفتحها وحذف الألف، بمعنى: ولا تأمرون بإطعام المسكين", "ashab": "", "athar": []}, {"n": 3, "t": "يحضون» بالياء وحذف الألف، بمعنى: ولا يكرم القائل إذا ما ابتلاه ربه فأكرمه ونعمه: ربي أكرمني، وإذا قدر عليه رزقه: ربي أهانني، اليتيم، ولا يحضون على طعام المسكين", "ashab": "", "athar": []}, {"n": 4, "t": "(تحآضون) بالتاء وضمها وإثبات الألف", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 7165, "mi": 1, "aya": 17, "alam": "ابن جرير", "fil": "ذكرها", "kind": "نقل", "ref": "24/ 378 - 379", "qawl": "", "nass": "تحضون", "qawaid": [], "tabi": ""}, {"taliq": 7165, "mi": 1, "aya": 17, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 379 بتصرف", "qawl": "", "nass": "قراءات معروفات في قراءة الأمصار، فبأي ذلك قرأ القارئ فمصيب", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "قراءة قوله تعالى: {فيومئذ لا يعذب عذابه أحد ولا يوثق وثاقه أحد}", "mawsua": {"taliq": 7170, "masala": "قراءة قوله تعالى: {فيومئذ لا يعذب عذابه أحد ولا يوثق وثاقه أحد}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{يعذب - يوثق} بكسر الذال والثاء", "ashab": "", "athar": []}, {"n": 2, "t": "يعذب - يوثق» بفتح الذال والثاء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 7170, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "24/ 393", "qawl": "", "nass": "وأما الذي قرأ ذلك بالفتح فإنه وجه تأويله إلى: فيومئذ لا يعذب أحد في الدنيا كعذاب الله يومئذ، ولا يوثق أحد في الدنيا كوثاقه يومئذ. وقد تأول ذلك بعض من قرأ ذلك كذلك بالفتح من المتأخرين: فيومئذ لا يعذب عذاب الكافر أحد، ولا يوثق وثاق الكافر أحد. وقال: كيف يجوز الكسر، ولا معذب يومئذ سوى الله؟!", "qawaid": [], "tabi": ""}, {"taliq": 7170, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 481 ط: دار الكتب العلمية", "qawl": "", "nass": "وعلى هذه القراءة، فالضمير عائد في {عذابه} و {وثاقه} لله تعالى، والمصدر مضاف إلى الفاعل، ولذلك معنيان: أحدهما: أن الله تعالى لا يكل عذاب الكفار يومئذ إلى أحد. والآخر: أن عذابه من الشدة في حيز لم يعذب قط أحد بمثله في الدنيا، ويحتمل أن يكون الضمير للكافر والمصدر مضاف إلى المفعول", "qawaid": [], "tabi": ""}, {"taliq": 7170, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 392", "qawl": "", "nass": "وهذا من التأويل غلط؛ لأن أهل التأويل تأولوه بخلاف ذلك، مع إجماع الحجة من القرأة على قراءته بالمعنى الذي جاء به تأويل أهل التأويل، وما أحسبه دعاه إلى قراءة ذلك كذلك إلا ذهابه عن وجه صحته في التأويل", "qawaid": ["القراءة ورسم المصحف", "غير ذلك", "أقوال السلف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف", "غير ذلك", "أقوال السلف"]}, "rulesD": {}}}, {"aya": 27, "title": "في تأويل ذلك ﴿ياأيتها النفس المطمئنة (٢٧) ارجعي إلى ربك راضية مرضية﴾", "tabari": {"page": "24/393", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "بل معنى ذلك : الموقنة بأن الله ربها، المسلمة لأمره فيما هو فاعل بها", "taqdim": 0, "n_athar": 9, "qailun": [["مجاهد", "تابعي"], ["أبي شيخ الهنائي", "تابعي"]], "athar": [83187, 83188, 83189]}, {"n": 2, "t": "إن ذلك قول الملك للعبد عند خروج نفسه يبشره برضا ربه عنه، وإعداده ما أعد له من الكرامة عنده", "taqdim": 0, "n_athar": 2, "qailun": [["سعيد", "تابعي"], ["أبي صالح", "تابعي"]], "athar": [83179]}, {"n": 3, "t": "ثنا ابن يمان، عن عن أسامة بن زيد، عن أبيه في قوله: ﴿ياأيتها النفس المطمئنة﴾، قال: بشرت بالجنة عند الموت، ويوم الجمع، وعند البعث", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 7171, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 397 - 398", "qawl": "الثاني", "nass": "لدلالة قوله: {فادخلي في عبادي وادخلي جنتي} على صحة ذلك، وأن دخولها الجنة إنما هو يومئذ لا قبل ذلك", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 7171, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "8/ 616", "qawl": "", "nass": "قال بعض العلماء: هذا النداء هو الآن للمؤمنين، كما ذكر الله تعالى حال الكافرين، قال: يا مؤمنون، دوموا وجدوا حتى ترجعوا راضين مرضيين، فالنفس -على هذا- اسم الجنس … وقال آخرون: هذا النداء إنما هو في الموقف عندما ينطلق بأهل النار إلى النار، فنداء النفوس -على هذا- إنما هو نداء أرباب النفوس مع النفوس، ومعنى {ارجعي إلى ربك} -على هذا-: إلى رحمة ربك", "qawaid": [], "tabi": ""}, {"taliq": 7171, "mi": 1, "aya": 28, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "3/ 300", "qawl": "", "nass": "أن هذا القول يقال لها عند الخروج من الدنيا، ويوم القيامة. فإن أول بعثها عند مفارقتها الدنيا، وحينئذ فهي في الرفيق الأعلى إن كانت مطمئنة إلى الله وفي جنته كما دلت عليه الأحاديث الصحيحة، فإذا كان يوم القيامة قيل لها ذلك، وحينئذ فيكون تمام الرجوع إلى الله، ودخول الجنة، فأول ذلك عند الموت، وتمامه ونهايته يوم القيامة، فلا اختلاف في الحقيقة", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 7171, "mi": 1, "aya": 28, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 350", "qawl": "الأول", "nass": "واختاره -أي: القول الثاني- ابن جرير، وهو غريب، والظاهر الأول؛ لقوله: {ثم ردوا إلى الله مولاهم الحق} [الأنعام: 62]، {وأن مردنا إلى الله} [غافر: 43] أي: إلى حكمه والوقوف بين يديه", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 9, "imgs": ["089_009_1.png"], "pages": [564], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 7171, "masala": "معنى: {ارجعي إلى ربك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ارجعي إلى ربك عند الموت في الدنيا", "ashab": "", "athar": []}, {"n": 2, "t": "ارجعي إلى جسدك عند البعث يوم القيامة، والرب هنا: صاحبها", "ashab": "", "athar": []}, {"n": 3, "t": "ارجعي إلى ثواب ربك في الآخرة", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]], "1": [["ابن كثير", "r"]]}, "t": {"3": [["ابن كثير", "r"]], "1": [["ابن جرير", "r"]]}, "gen": [["ابن القيم", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["السياق"], "ابن القيم": ["الدلالة العقلية"], "ابن كثير": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 28, "title": "في تأويله", "tabari": {"page": "24/396", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب القول الذي ذكرناه عن ابن عباس والضحاك؛ أن ذلك إنما يقال لهم عند رد الأرواح في الأجساد يوم البعث، لدلالة", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هذا خبر من الله جل ثناؤه عن قيل الملائكة لنفس المؤمن عند البعث، تأمرها أن ترجع في جسد صاحبها. قالوا: وعنى بالرب ههنا صاحبها", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["عكرمة في هذه الآية", "تابعي"]], "athar": [83201, 83209, 83214, 83215]}, {"n": 2, "t": "بل يقال ذلك لها عند الموت", "taqdim": 0, "n_athar": 1, "qailun": [["أبي صالح", "تابعي"]], "athar": [83208]}]}, "mawaqif": [], "mushid": {"i": 10, "imgs": ["089_010_1.png"], "pages": [564], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "قراءة قوله تعالى: {فادخلي في عبادي}", "mawsua": {"taliq": 7172, "masala": "قراءة قوله تعالى: {فادخلي في عبادي}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{فادخلي في عبادي} بإثبات الألف", "ashab": "", "athar": []}, {"n": 2, "t": "(فادخلي في عبدي) بحذف الألف", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 7172, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "8/ 616", "qawl": "", "nass": "فالنفس -على هذا- ليست باسم الجنس، وإنما خاطب مفردة", "qawaid": [], "tabi": ""}, {"taliq": 7172, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 400", "qawl": "", "nass": "", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 30, "title": "في معنى ذلك ﴿فادخلي في عبادي (٢٩) وادخلي جنتي﴾", "tabari": {"page": "24/398", "sarih": 1, "tarjih": "والصواب من القراءة في ذلك ﴿فادخلي في عبادي﴾ بمعنى: فادخلى في عبادى الصالحين؛ لإجماع الحجة من القرأة عليه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معناه: فادخلي في عبادي الصالحين، وادخلي جنتي", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": []}, {"n": 2, "t": "معنى ذلك: فادخلي في طاعتي وادخلى جنتي", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "حدثني أحمد بن يوسف، قال: ثنا القاسم بن سلام، قال: ثنا حجاج، عن هارون، عن أبان بن أبي عياش، عن سليمان بن قتة، عن ابن عباس، أنه قرأها: (فادخلي في عبدى). على التوحيد", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 11, "imgs": ["089_011_1.png"], "pages": [564], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 7150, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (8/ 604) أنّ سورة الفجر «مكّيّة عند جمهور المفسرين». ونقل عن بعض العلماء -حكاية عن الداني-: أنها مدنية، ثم رجَّح قائلًا: «والأول أشهر، وأصحّ». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 7150, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 604", "qawl": "", "nass": "مكية عند جمهور المفسرين", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "4": [{"id": 7154, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (8/ 606) أنّ «سُرى الليل: ذهابه وانقراضه، هذا قول الجمهور». ثم نقل عن ابن قُتيبة، والأخفش وغيرهما أنّ المعنى: «إذا يُسرى فيه». ثم وجَّهه بقوله: «فيخرج هذا الكلام مخرج: ليل نائم، ونهار صائم».", "mawaqif": [{"taliq": 7154, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 606", "qawl": "", "nass": "سرى الليل: ذهابه وانقراضه، هذا قول الجمهور", "qawaid": [], "tabi": ""}]}, {"id": 7155, "kinds": "توجيه،تعليق", "text": "علَّق ابنُ كثير (14/ 342) على قول أبي العالية وما في معناه بقوله: «وهذا يمكن حمْله على ما قال ابن عباس، أي: ذهب. ويحتمل أن يكون المراد: إذا سار، أي: أقبل. وقد يقال: إنّ هذا أنسب؛ لأنه في مقابلة قوله: {والفَجْرِ}، فإنّ الفجر هو إقبال النهار وإدبار الليل، فإذا حمل قوله: {واللَّيْلِ إذا يَسْرِ} على إقباله كان قَسمًا بإقبال الليل وإدبار النهار، وبالعكس، كقوله: {واللَّيْلِ إذا عَسْعَسَ والصُّبْحِ إذا تَنَفَّسَ} [التكوير: 17 - 18]».", "mawaqif": [{"taliq": 7155, "mi": 0, "aya": 4, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "14/ 342", "qawl": "أبي العالية", "nass": "وهذا يمكن حمله على ما قال ابن عباس، أي: ذهب. ويحتمل أن يكون المراد: إذا سار، أي: أقبل. وقد يقال: إن هذا أنسب؛ لأنه في مقابلة قوله: {والفجر}، فإن الفجر هو إقبال النهار وإدبار الليل، فإذا حمل قوله: {والليل إذا يسر} على إقباله كان قسما بإقبال الليل وإدبار النهار، وبالعكس، كقوله: {والليل إذا عسعس والصبح إذا تنفس} [التكوير: 17 - 18]", "qawaid": [], "tabi": ""}]}], "5": [{"id": 7156, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (24/ 360) في معنى: {لِذِي حِجْرٍ} سوى قول ابن عباس من طريق أبي نصر، وما في معناه.", "mawaqif": []}], "9": [{"id": 7160, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (8/ 608) أنّ «الوادي: ما بين الجبلين وإن لم يكن فيه ماءٌ. هذا قول كثير من المفسرين في معنى {جابُوا الصَّخْرَ بِالوادِ}». ثم نقل عن الثعلبي أنّ المراد: «بوادي القرى». ونقل عن قوم أنّ «المعنى: جابوا واديهم، وجلبوا ماءهم في صخر شقُّوه». ثم علَّق بقوله: «وهذا فعل ذي القوة والآمال».", "mawaqif": [{"taliq": 7160, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 608", "qawl": "", "nass": "الوادي: ما بين الجبلين وإن لم يكن فيه ماء. هذا قول كثير من المفسرين في معنى {جابوا الصخر بالواد}", "qawaid": [], "tabi": ""}]}], "14": [{"id": 7162, "kinds": "نقد،بيان،نقل", "text": "ذكر ابن القيم (3/ 296) أن «قوله تعالى: {والفجر وليال عشر والشفع والوتر والليل إذا يسر هل في ذلك قسم لذي حجر}؛ قيل جوابه: {إن ربك لبالمرصاد}». ثم انتقد هذا القول -مستندًا إلى الدلالة العقلية والسياق- فقال: «وهذا ضعيف لوجهين: أحدهما: طول الكلام والفصل بين القسم وجوابه بجمل كثيرة، والثاني: قوله: {إن ربك لبالمرصاد} ذُكِرَ تقريرًا لعقوبة الله الأمم المذكورة، وهي عاد وثمود وفرعون، فذكر عقوبتهم ثم قال مقرِّرًا ومحذِّرًا: {إن ربك لبالمرصاد}، أفلا ترى تعلقه بذلك دون القسم؟!».", "mawaqif": [{"taliq": 7162, "mi": 0, "aya": 14, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "3/ 296", "qawl": "", "nass": "قوله تعالى: {والفجر وليال عشر والشفع والوتر والليل إذا يسر هل في ذلك قسم لذي حجر}؛ قيل جوابه: {إن ربك لبالمرصاد}", "qawaid": ["الدلالة العقلية", "السياق"], "tabi": ""}]}, {"id": 7163, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (8/ 609) نقلًا عن اللغويين أنّ «المرصاد»: موضع الرصد، ثم وجَّهه بقوله: «أي أنه عند لسان كلِّ قائل، ومرصدٌ لكل فاعل، وعلى هذا التأويل في المرصاد جاء جواب عامر بن قيس لعثمان رضي الله عنهما حين قال له: أين ربّك، يا أعرابي؟ قال: بالمرصاد». ثم ذكر احتمالًا آخر: «أن يكون» المرصاد «في الآية اسم فاعل». ثم وجَّهه بقوله: «كأنه تعالى قال: لَبِالرّاصد، فعبَّر ببناء مبالغة، وروي في بعض الحديث «إنّ على جسر جهنم ثلاث قناطر، على إحداها الأمانة، وعلى الأخرى الرَّحِم، وعلى الأخيرة الرّبّ تعالى، فذلك قوله: {إن رَبَّكَ لَبِالمِرْصادِ}»».", "mawaqif": [{"taliq": 7163, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 609", "qawl": "", "nass": "المرصاد»: موضع الرصد، ثم وجهه بقوله: «أي أنه عند لسان كل قائل، ومرصد لكل فاعل، وعلى هذا التأويل في المرصاد جاء جواب عامر بن قيس لعثمان رضي الله عنهما حين قال له: أين ربك، يا أعرابي؟ قال: بالمرصاد", "qawaid": [], "tabi": ""}]}], "15": [{"id": 7164, "kinds": "ترجيح،نقد،نقل", "text": "أفادت الآثار أنّ معنى: {كلا} في هذه الآية، أي: أنّ الله أنكر أن يكون سبب كرامته مَن أكرم كثرةَ ماله، وسبب إهانة مَن أهان قِلّةَ ماله. ونقل ابنُ جرير (24/ 378 بتصرف) عن آخرين: «أنّ الله -جلَّ ثناؤه- أنكر حَمْدَ الإنسان ربَّه على نِعَمِه دون فقره، وشكواه الفاقة، وقالوا: معنى الكلام: كلا، أي: لم يكن ينبغي أن يكون هكذا، ولكن كان ينبغي أن يحمَدَه على الأمرين جميعًا؛ على الغنى والفقر». ثم رجَّح (24/ 378) القول الأول مستندًا إلى السياق، وعلَّل ذلك بقوله: «لدلالة قوله: {بَلْ لا تُكْرِمُونَ اليَتِيمَ} والآيات التي بعدها على أنّه إنّما أهان مَن أهان بأنه لا يُكرِم اليتيم، ولا يحضّ على طعام المسكين، وسائر المعاني التي عدّد، وفي إبانته عن السبب الذي من أجله أهان مَن أهان الدلالة الواضحة على سبب تكريمه من أكرم، وفي تَبْيِينه ذلك عَقِيب قوله: {فَأَمّا الإنْسانُ إذا ما ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ ونَعَّمَهُ فَيَقُولُ رَبِّي أكْرَمَن وأَمّا إذا ما ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أهانَنْ} بيانٌ واضحٌ عن أنّ الذي أنكر مِن قوله ما وصفنا».", "mawaqif": [{"taliq": 7164, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "24/ 378 بتصرف", "qawl": "", "nass": "أن الله -جل ثناؤه- أنكر حمد الإنسان ربه على نعمه دون فقره، وشكواه الفاقة، وقالوا: معنى الكلام: كلا، أي: لم يكن ينبغي أن يكون هكذا، ولكن كان ينبغي أن يحمده على الأمرين جميعا؛ على الغنى والفقر", "qawaid": ["السياق"], "tabi": ""}]}], "17": [{"id": 7166, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (8/ 612) أنّ «{طعام} في هذه الآية بمعنى: إطعام». ثم نقل عن قوم قولهم: «أراد: نفس طعامه الذي يأكل». ثم وجَّهه بقوله: «ففي الكلام حذف، تقديره: على بذل طعام المسكين».", "mawaqif": [{"taliq": 7166, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 612", "qawl": "", "nass": "{طعام} في هذه الآية بمعنى: إطعام", "qawaid": [], "tabi": ""}]}], "21": [{"id": 7167, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (24/ 383) في معنى: {إذا دُكَّتِ الأَرْضُ دَكًّا دَكًّا} سوى قول ابن عباس.", "mawaqif": []}], "23": [{"id": 7168, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 614): «ورُوي أنه لما نزلت: {وجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ} تغيّر لون النبي صلى الله عليه وسلم».", "mawaqif": [{"taliq": 7168, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 614", "qawl": "", "nass": "وروي أنه لما نزلت: {وجيء يومئذ بجهنم} تغير لون النبي صلى الله عليه وسلم", "qawaid": [], "tabi": ""}]}], "24": [{"id": 7169, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (5/ 481 ط: دار الكتب العلمية) أقوالًا أخرى في معنى الآية، وعلَّق على بعضها، فقال: «وقال قوم من المتأولين: المعنى: لِحَياتِي في قبري عند بعْثي الذي كنت أُكَذِّب به وأعتقد أني لن أعود حيًّا. وقال آخرون: {لِحَياتِي} هنا مجازًا، أي: لَيْتَنِي قَدَّمْتُ عملًا صالحًا لأنعم به اليوم وأحيا حياةً طيّبة. فهذا كما يقول الإنسان: أحيني في هذا الأمر. وقال بعض المتأولين: المعنى: لوقت أو لمدة حياتي الماضية في الدنيا، وهذا كما تقول: جئت لطلوع الشمس ولتاريخ كذا ونحوه».", "mawaqif": [{"taliq": 7169, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 481 ط: دار الكتب العلمية", "qawl": "", "nass": "وقال قوم من المتأولين: المعنى: لحياتي في قبري عند بعثي الذي كنت أكذب به وأعتقد أني لن أعود حيا. وقال آخرون: {لحياتي} هنا مجازا، أي: ليتني قدمت عملا صالحا لأنعم به اليوم وأحيا حياة طيبة. فهذا كما يقول الإنسان: أحيني في هذا الأمر. وقال بعض المتأولين: المعنى: لوقت أو لمدة حياتي الماضية في الدنيا، وهذا كما تقول: جئت لطلوع الشمس ولتاريخ كذا ونحوه", "qawaid": [], "tabi": ""}]}], "28": [{"id": 7173, "kinds": "خلاف،نقل", "text": "زاد ابنُ جرير (24/ 398) في معنى: {فادْخُلِي فِي عِبادِي} نقلًا عن أهل العربية قولين آخرين، فقال: «وكان بعض أهل العربية من أهل البصرة يوجِّه معنى قوله: {فادْخُلِي فِي عِبادِي} إلى: فادخلي في حزبي. وكان بعض أهل العربية من أهل الكوفة يتأوَّل ذلك: {يا أيَّتُها النَّفْسُ المُطْمَئِنَّةُ} بالإيمان، والمصدِّقة بالثواب والبعث {ارْجِعِي}، تقول لهم الملائكة إذا أُعطُوا كُتبهم بأيمانهم: {ارْجِعِي إلى رَبِّكِ} إلى ما أعدَّ الله لكِ من الثواب. قال: وقد يكون أن تقول لهم هذا القولَ ينْوون: ارجِعوا من الدنيا إلى هذا المرجع، قال: وأنتَ تقول للرجل: ممن أنتَ؟ فيقول: مُضَريٌّ. فتقولُ: كن تميميًّا أو قيسيًّا، أي: أنتَ من أحد هذين. فتكون» كن «صلة، كذلك الرجوع يكون صلة؛ لأنه قد صار إلى القيامة، فكان الأمر بمعنى الخبر، كأنه قال: أيَّتُها النفس، أنتِ راضيةٌ مرضيةٌ».", "mawaqif": [{"taliq": 7173, "mi": 0, "aya": 28, "alam": "ابن جرير", "fil": "زاد", "kind": "نقل", "ref": "24/ 398", "qawl": "", "nass": "وكان بعض أهل العربية من أهل البصرة يوجه معنى قوله: {فادخلي في عبادي} إلى: فادخلي في حزبي. وكان بعض أهل العربية من أهل الكوفة يتأول ذلك: {يا أيتها النفس المطمئنة} بالإيمان، والمصدقة بالثواب والبعث {ارجعي}، تقول لهم الملائكة إذا أعطوا كتبهم بأيمانهم: {ارجعي إلى ربك} إلى ما أعد الله لك من الثواب. قال: وقد يكون أن تقول لهم هذا القول ينوون: ارجعوا من الدنيا إلى هذا المرجع، قال: وأنت تقول للرجل: ممن أنت؟ فيقول: مضري. فتقول: كن تميميا أو قيسيا، أي: أنت من أحد هذين. فتكون", "qawaid": [], "tabi": ""}]}]}, "athar": {"83065": {"num": 83065, "aya": 10, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبَير -من طريق محمود- {وفِرْعَوْنَ ذِي الأَوْتادِ}، قال: كان يجعل رِجلًا هنا ورِجلًا هنا، ويَدًا هنا ويَدًا هنا، بالأوتاد."}, "83201": {"num": 83201, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس-من طريق عطية العَوفيّ- في قوله: {ارْجِعِي إلى رَبِّكِ}، قال: تُردّ الأرواح يوم القيامة في الأجساد."}, "82949": {"num": 82949, "aya": 3, "qail": "عمران بن حصين", "tabaqa": "صحابي", "bab": "", "text": "عن عمران بن حصين، أنّ النبي صلى الله عليه وسلم سُئِل عن الشفع والوتر. فقال: «هي الصلاة؛ بعضها شفعٌ، وبعضها وترٌ»."}, "82950": {"num": 82950, "aya": 3, "qail": "جابر", "tabaqa": "صحابي", "bab": "", "text": "عن جابر، أنّ النبي صلى الله عليه وسلم قال: «{والشَّفْعِ والوَتْرِ}، والوتر يوم عرفة، والشَّفع يوم النَّحر»."}, "82951": {"num": 82951, "aya": 3, "qail": "جابر", "tabaqa": "صحابي", "bab": "", "text": "عن جابر، أنّ رسول الله صلى الله عليه وسلم قال: «الشَّفع اليومان، والوتر اليوم الثالث»."}, "83066": {"num": 83066, "aya": 10, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبَير -من طريق رجل- قال: إنما سُمّي فرعون: ذا الأوتاد؛ لأنه كان يُبنى له المنابر يَذبح عليها الناس."}, "83209": {"num": 83209, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {ارْجِعِي إلى رَبِّكِ راضِيَةً} قال: بما أُعطيتْ مِن الثواب، {مَرْضِيَّةً} عنها بعملها."}, "83208": {"num": 83208, "aya": 28, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق إسماعيل بن أبي خالد- في قوله: {ارْجِعِي إلى رَبِّكِ} قال: هذا عند الموت، رجوعها إلى ربّها خروجها من الدنيا، فإذا كان يوم القيامة قيل لها: {فادْخُلِي فِي عِبادِي وادْخُلِي جَنَّتِي}."}, "83083": {"num": 83083, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {إنَّ رَبَّكَ لَبِالمِرْصادِ}، قال: يسمع ويرى."}, "82956": {"num": 82956, "aya": 3, "qail": "عمران بن حصين", "tabaqa": "صحابي", "bab": "", "text": "عن عمران بن حصين -من طريق قتادة- {والشَّفْعِ والوَتْرِ}، قال: الصلاة المكتوبة؛ منها شفعٌ، ومنها وترٌ."}, "82957": {"num": 82957, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {والشَّفْعِ والوَتْرِ}، قال: الله وترٌ، وأنتم شفعٌ. ويقال: الشَّفع: صلاة الغداة، والوتر: صلاة المغرب."}, "82958": {"num": 82958, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {والشَّفْعِ والوَتْرِ}، قال: الشَّفع: يوم النَّحر، والوتر: يوم عرفة."}, "82959": {"num": 82959, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {والشَّفْعِ والوَتْرِ}، قال: كل شيء شفع فهو اثنان، والوتر واحد."}, "82960": {"num": 82960, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية-: {الشَّفْعِ} صلاة الغداة، {والوَتْرِ} صلاة المغرب."}, "82961": {"num": 82961, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: الوتر: آدم، شُفِع بزوجته."}, "83085": {"num": 83085, "aya": 14, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق معمر- {إنَّ رَبَّكَ لَبِالمِرْصادِ}، قال: بمرصاد أعمال بني آدم."}, "83214": {"num": 83214, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق سليمان بن قتّة- أنه قرأها: (فادْخُلِي فِي عَبْدِي) على التوحيد."}, "82964": {"num": 82964, "aya": 3, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر-، مثله."}, "83069": {"num": 83069, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- قال: ذي البناء، كانت مظالّ يُلعب له تحتها، وأوتاد تُضرب له."}, "82966": {"num": 82966, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق معمر، عن ابن أبي نجيح- {والشَّفْعِ والوَتْرِ}، قال: الخَلْق كلّه شفعٌ ووتر، فأَقسم بالخَلْق."}, "82967": {"num": 82967, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ورقاء، عن ابن أبي نجيح- {والشَّفْعِ والوَتْرِ} قال: كلّ خَلْق الله شفعٌ؛ السماء والأرض، والبَرّ والبحر، والإنس والجن، والشمس والقمر، ونحو هذا شفعٌ، والوتر الله وحده."}, "82968": {"num": 82968, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- {والشفع والوتر}، قال: الشَّفع: الزوج، والوتر: الله."}, "82969": {"num": 82969, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، {والشَّفْعِ والوَتْرِ}، قال: الله الوتر، وخَلْقه الشَّفع؛ الذَّكَر والأنثى."}, "82970": {"num": 82970, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، قال: الشَّفع: آدم وحواء، والوتر: الله."}, "82971": {"num": 82971, "aya": 3, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق أبي سنان- قال: {ولَيالٍ عَشْرٍ والشَّفْعِ والوَتْرِ}، الشَّفع: يوم النَّحر، والوتر: يوم عرفة، أقسم بهما ربّهما لفضْلهما على العَشر."}, "83070": {"num": 83070, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {وفِرْعَوْنَ ذِي الأَوْتادِ} كان إذا غضب على أحد أوتد له في الأرض أربعة أوتاد على يديه ورجليه."}, "83093": {"num": 83093, "aya": 14, "qail": "سفيان الثوري", "tabaqa": "تابع التابعين", "bab": "", "text": "عن سفيان [الثوري]-من طريق مهران- {إنَّ رَبَّكَ لَبِالمِرْصادِ}: يعني: جهنم عليها ثلاث قناطر؛ قنطرة فيها الرحمة، وقنطرة فيها الأمانة، وقنطرة فيها الرّبّ تبارك وتعالى."}, "83215": {"num": 83215, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {فادْخُلِي فِي عِبادِي}: المؤمنين."}, "82977": {"num": 82977, "aya": 3, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح [باذام]-من طريق إسماعيل- {والشَّفْعِ والوَتْرِ}، قال: خَلَق الله مِن كلّ زوجين اثنين، والله وترٌ واحد صمد. ="}, "82979": {"num": 82979, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {والشَّفْعِ والوَتْرِ}، قال: إنّ من الصلاة شفعًا، وإنّ منها وترًا. ="}, "82981": {"num": 82981, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {والشَّفْعِ والوَتْرِ} الشَّفع: الخَلْق، والوتر: الله تعالى."}, "83063": {"num": 83063, "aya": 10, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق إسحاق بن بشر، عن ابن سمعان، عن عطاء- أنّ فرعون إنما سُمّي {ذي الأوتاد} لأنه كانت امرأة -وهي امرأة خازن فرعون حزبيل، وكان مؤمنًا كتم إيمانه مائة سنة، وكانت امرأته ماشطة بنت فرعون- فبينما هي ذات يوم تمشط رأس بنت فرعون إذ سقط المشط من يدها، فقالت: تعس مَن كفر بالله. فقالت بنت فرعون: وهل لك مِن إلهٍ غير أبي؟ فقالت: إلهي وإله أبيك وإله السماوات والأرض واحد لا شريك له. فقامت، فدخلت على أبيها وهي تبكي، فقال: ما يبكيك؟ قالت: الماشطة امرأة خازنك تزعم أنّ إلهك وإلهها وإله السماوات والأرض واحد لا شريك له. فأرسَل إليها، فسألها عن ذلك، فقالت: صدقتْ. فقال لها: ويحكِ، اكفري بإلهكِ وأقِرِّي بأني إلهكِ. قالت: لا أفعل. فمدَّها بين أربعة أوتاد، ثم أرسَل عليها الحيّات والعقارب، وقال لها: اكفري بإلهكِ، وإلا عذّبتُك بهذا العذاب شهرين. فقالت له: ولو عذَّبتني سبعين شهرًا ما كفرتُ بالله. وكان لها ابنتان، فجاء بابنتها الكبرى، فذبحها على قُربٍ منها، وقال لها: اكفري بالله، وإلا ذبحتُ الصغرى على قلبكِ. وكانت رضيعًا، فقالتْ: لو ذبحتَ مَن على وجه الأرض على فِيَّ ما كفرتُ بالله عز وجل. فأتى بابنتها الصغرى، فلما أُضجعتْ على صدرها وأرادوا ذبحها جزعت المرأة، فأطلق الله لسان ابنتها، فتكلّمتْ، وهي مِن الأربعة الذين تَكلّموا أطفالًا، وقالت: يا أُمّاه، لا تجزعي؛ فإنّ الله قد بنى لكِ بيتًا في الجنة، اصبري فإنّك تُفْضِين إلى رحمة الله وكرامته. فذُبحتْ، فلم تلبث أن ماتتْ، فأسكنها الله الجنة. قال: وبعث في طلب زوجها حزبيل، فلم يقدروا عليه، فقيل لفرعون: إنّه قد رُئِي في موضع كذا وكذا في جبل كذا. فبعث رجلين في طلبه، فانتهيا إليه وهو يُصلّي، ويليه صفوف من الوحوش خلفه يُصلُّون، فلمّا رأيا ذلك انصرفا، فقال حزبيل: اللهم، إنّك تعلم أنّي كتمتُ إيماني مائة سنة، ولم يظهر عَلَيَّ أحد، فأيّما هذان الرجلين كتم عليَّ فاهدِه إلى دينك، وأَعْطِه مِن الدنيا سُؤْلَه، وأيّما هذين الرجلين أظهر عليَّ فعجِّل عقوبته في الدنيا، واجعل مصيره في الآخرة إلى النار. فانصرف الرجلان إلى فرعون، فأمّا أحدهما فاعتبر وآمن، وأمّا الآخر فأخبر فرعون بالقصة على رؤوس الملأ، فقال له فرعون: وهل كان معك غيرك؟ قال: نعم، فلان. فدعا به، فقال: أحقٌّ ما يقول هذا؟ قال: لا، ما رأيتُ مما قال شيئًا. فأعطاه فرعون وأجزل، وأمّا الآخر فقتله، ثم صلبه. قال: وكان فرعون قد تزوج امرأة مِن نساء بني إسرائيل يقال لها: آسية بنت مزاحم، فرأتْ ما صنع فرعونُ بالماشطة، فقالت: وكيف يسعني أنْ أصبر على ما يأتي به فرعون، وأنا مسلمة وهو كافر؟ فبينما هي كذلك تُؤامِر نفسها إذ دخل عليها فرعون، فجلس قريبًا منها، فقالت: يا فرعون، أنتَ شرُّ الخَلْق وأخبثهم، عمدتَ إلى الماشطة فقتلتَها! قال: فلعلّ بك الجنون الذي كان بها؟ قالت: ما بي مِن جنون، وإنّ إلهي وإلهها وإلهك وإله السماوات والأرض واحد لا شريك له. فمزَّق عليها ثيابها، وضربها، وأرسَل إلى أبويها فدعاهما، فقال لهما: ألا تريان أنّ الجنون الذي كان بالماشطة أصابها؟ قالت: أعوذ بالله مِن ذلك، إني أشهد أنّ ربي وربَّك وربّ السماوات والأرض واحدٌ لا شريك له. فقال لها أبوها: يا آسية، ألستِ مِن خير نساء العماليق، وزوجكِ إله العماليق؟ قالت: أعوذ بالله مِن ذلك، إن كان ما يقول حقًّا فقولا له أن يتوّجني تاجًا تكون الشمس أمامه، والقمر خلفه، والكواكب حوله. فقال لهما فرعون: اخرجا عني. فمدَّها بين أربعة أوتاد يُعذّبها، ففتح الله لها بابًا إلى الجنة ليهون عليها ما يصنع بها فرعون، فعند ذلك قالت: {رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظالمين} [التحريم: 11]. فقبض الله روحها، وأسكنها الجنة."}, "82989": {"num": 82989, "aya": 4, "qail": "عبد الله بن الزبير", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن الزُّبير -من طريق محمد بن المرتفع- {واللَّيْلِ إذا يَسْرِ}، قال: حتى يُذهِب بعضُه بعضًا."}, "82990": {"num": 82990, "aya": 4, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحيّ، {واللَّيْلِ إذا يَسْرِ}، يقول: إذا أقبل."}, "82991": {"num": 82991, "aya": 4, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحيّ -من طريق الربيع- {واللَّيْلِ إذا يَسْرِ}، قال: والليل إذا سار."}, "82992": {"num": 82992, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر ="}, "82994": {"num": 82994, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- {واللَّيْلِ إذا يَسْرِ}، قال: إذا سار."}, "82998": {"num": 82998, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {واللَّيْلِ إذا يَسْرِ}، قال: إذا سار."}, "83001": {"num": 83001, "aya": 4, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {واللَّيْلِ إذا يَسْرِ}، قال: الليل إذا يسير."}, "83034": {"num": 83034, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {ذاتِ العِمادِ}: يعني: طولهم مثل العماد."}, "83035": {"num": 83035, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ذاتِ العِمادِ}، قال: أهل عمود، لا يُقيمُون."}, "82908": {"num": 82908, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي نصر- في قوله: {والفَجْرِ}، قال: فجر النهار."}, "83036": {"num": 83036, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- في قوله: {ذاتِ العِمادِ}، قال: كان لها جسم في السماء."}, "82911": {"num": 82911, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {والفَجْرِ}، قال: يعني: صلاة الفجر."}, "82912": {"num": 82912, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عثمان- في قوله: {والفَجْرِ}، قال: هو المُحرّم أول فجر السنة."}, "82913": {"num": 82913, "aya": 1, "qail": "عبد الله بن الزبير", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن الزُّبير -من طريق محمد بن المرتفع- في قوله: {والفَجْرِ}، قال: قَسمٌ أقسم الله به."}, "83039": {"num": 83039, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {ذاتِ العِمادِ}، قال: ذُكر لنا: أنهم كانوا أهل عمود، لا يقيمون؛ سيّارة."}, "83044": {"num": 83044, "aya": 7, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إرَمَ ذاتِ العِمادِ}، قال: عاد قوم هود، بَنَوها وعملوها حين كانوا في الأحقاف."}, "83046": {"num": 83046, "aya": 8, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {الَّتِي لَمْ يُخْلَقْ مِثْلُها فِي البِلادِ}، قال: ذُكر لنا: أنهم كانوا اثني عشر ذراعًا طولًا في السماء."}, "83179": {"num": 83179, "aya": 27, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن سعيد بن جُبَير، قال: قُرئتْ عند النبي صلى الله عليه وسلم: {يا أيَّتُها النَّفْسُ المُطْمَئِنَّةُ ارْجِعِي إلى رَبِّكِ راضِيَةً مَرْضِيَّةً}، فقال أبو بكر: إنّ هذا لَحَسن! فقال رسول الله صلى الله عليه وسلم: «أما إنّ المَلَك سيقولها لك عند الموت»."}, "83188": {"num": 83188, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {يا أيَّتُها النَّفْسُ المُطْمَئِنَّةُ}، قال: التي أيقنتْ بأنّ الله ربها، وضربتْ لأمر الله جأشًا."}, "82925": {"num": 82925, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي نصر- في قوله: {ولَيالٍ عَشْرٍ}، قال: عشرة الأضحى. وفي لفظ قال: هي ليال العشر الأُوَل من ذي الحِجّة."}, "82926": {"num": 82926, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {ولَيالٍ عَشْرٍ}، قال: هي العشر الأواخر من رمضان."}, "82927": {"num": 82927, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- {ولَيالٍ عَشْرٍ}: عَشرُ الأضحى. قال: ويقال: العشر: أول السنة مِن المُحرّم."}, "82928": {"num": 82928, "aya": 2, "qail": "عبد الله بن الزبير", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن الزُّبير -من طريق محمد بن المرتفع- في قوله: {ولَيالٍ عَشْرٍ}، قال: أول ذي الحِجّة إلى يوم النَّحر."}, "83189": {"num": 83189, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {يأيتها النفس المطمئنة}، قال: الراضية بقضاء الله الذي قدّر الله، فعلمتْ أنّ ما أصابها لم يكن ليُخطئها، وأنّ ما أخطأها لم يكن ليُصيبها."}, "83187": {"num": 83187, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {يا أيَّتُها النَّفْسُ المُطْمَئِنَّةُ}، قال: المُخبِتة إلى الله."}, "82932": {"num": 82932, "aya": 2, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأَجْدع الهَمداني -من طريق أبي الضُّحى- في قوله: {ولَيالٍ عَشْرٍ}، قال: هي عَشرُ الأضحى، هي أفضل أيام السنة."}, "82933": {"num": 82933, "aya": 2, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأَجْدع الهَمداني، {ولَيالٍ عَشْرٍ}، قال: عَشرُ الأضحى، وهي التي وعد الله موسى؛ قوله: {وأَتْمَمْناها بِعَشْرٍ} [الأعراف: 142]."}, "82934": {"num": 82934, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولَيالٍ عَشْرٍ}، قال: عَشرُ ذي الحِجّة."}, "82935": {"num": 82935, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر-، مثله."}, "83061": {"num": 83061, "aya": 10, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {وفِرْعَوْنَ ذِي الأَوْتادِ}، قال: الأوتاد: الجنود الذين يُشدِّدون له أمره."}, "82937": {"num": 82937, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق يزيد بن أبي زياد- قال: ليس عملٌ في ليالٍ مِن ليالي السنة أفضل منه في ليالي العشر، وهي عَشرُ موسى التي أتمّها الله له."}, "83062": {"num": 83062, "aya": 10, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبَير-: أنه كانت له مظالٌّ يُلعب له تحتها، وأوتاد كانت تُضرب له."}, "83067": {"num": 83067, "aya": 10, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {وفِرْعَوْنَ ذِي الأَوْتادِ}، قال: كان يَتِد الناس بالأوتاد."}, "83064": {"num": 83064, "aya": 10, "qail": "أبي رافع", "tabaqa": "صحابي", "bab": "", "text": "عن أبي رافع -من طريق ثابت البُناني- قال: وتَّد فرعونُ لامرأته أربعةَ أوتاد، ثم جعل على ظهرها رحًا عظيمة حتى ماتت."}, "82941": {"num": 82941, "aya": 2, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولَيالٍ عَشْرٍ}، قال: أول ذي الحِجّة."}, "82942": {"num": 82942, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، عن رسول الله صلى الله عليه وسلم، قال: «ما مِن أيام فيهنّ العمل أحبّ إلى الله عز وجل أفضل مِن أيام العشر». قيل: يا رسول الله، ولا الجهاد في سبيل الله؟ قال: «ولا الجهاد في سبيل الله، إلا رجل جاهد في سبيل الله بماله ونفسه فلم يرجع من ذلك بشيء»."}, "82943": {"num": 82943, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم: «ما مِن أيام أفضل عند الله، ولا العمل فيهنّ أحبّ إلى الله عز وجل، مِن هذه الأيام العشر، فأكثِروا فيهنَّ مِن التهليل والتكبير، فإنها أيام التهليل والتكبير وذِكْر الله، وإنّ صيام يوم منها يَعدِل بصيام سنة، والعمل فيهنّ يُضاعف بسبعمائة ضعف»."}}, "n_athar": {"0": 10, "1": 16, "2": 26, "3": 39, "4": 14, "5": 31, "7": 13, "8": 5, "9": 9, "10": 14, "11": 2, "13": 5, "14": 14, "15": 7, "17": 7, "19": 15, "20": 12, "21": 4, "22": 10, "23": 14, "24": 6, "25": 6, "27": 25, "28": 25}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});